import{_ as a,o as t,c as o,a6 as s}from"./chunks/framework.CKIbuWFA.js";const p=JSON.parse('{"title":"実行時変数の再利用と変更の確認","description":"","frontmatter":{"title":"実行時変数の再利用と変更の確認","docId":"user.automations.variables","translationKey":"user.automations.variables","locale":"ja","audience":"user","featureStatus":"available","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"20ba9e681b63ffa9aff2ff5d868738d242fd4eab4d520d9e08656760ee8361ba","translationRevision":"5faf74b40793f8dbb7be6d879899f6481adf7ad470285079ae03832801f1edf2","order":40},"headers":[],"relativePath":"ja/user/automations/variables.md","filePath":"ja/user/automations/variables.md","lastUpdated":1794611623000}'),r={name:"ja/user/automations/variables.md"};function l(i,e,d,n,c,u){return t(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="reuse-and-review-runtime-variables" tabindex="-1">実行時変数の再利用と変更の確認 <a class="header-anchor" href="#reuse-and-review-runtime-variables" aria-label="Permalink to &quot;実行時変数の再利用と変更の確認 {#reuse-and-review-runtime-variables}&quot;">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">目的と前提条件 <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to &quot;目的と前提条件 {#goal-and-prerequisites}&quot;">​</a></h2><p>共有値を一度変更し、複数のアクションで再利用します。<strong>自動化 → 変数</strong> と、対象の変数操作に対応するホストが必要です。型付き編集や確認を伴う Cloud 操作はホスト機能に応じて表示されます。ローカル保存にアップロードは不要です。</p><h2 id="save-a-local-value" tabindex="-1">ローカル値を保存する <a class="header-anchor" href="#save-a-local-value" aria-label="Permalink to &quot;ローカル値を保存する {#save-a-local-value}&quot;">​</a></h2><ol><li><code>showLabel</code> という変数を追加します。キーは英字かアンダースコアで始め、英数字、ドット、アンダースコア、ハイフンを含められます。上限は <code>64</code> 文字です。キーの重複を避けます。</li><li>型付き編集が利用できる場合、テキストを選び <code>夜の配信</code> と入力します。他に数値、真偽値、リスト、シークレットを利用できます。リストは <code>[&quot;赤&quot;, &quot;青&quot;]</code> などの文字列の JSON 配列です。</li><li><strong>グローバル変数を保存</strong> を選びます。リビジョン競合は保存済みコレクションが変わったことを意味するため、再読み込みして変更内容を照合します。</li><li>テンプレート対応のアクション欄で保存値を使います。</li></ol><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>{{ globals.showLabel }}: {{ event.user.uniqueId }}</span></span></code></pre></div><ol start="5"><li>ログだけのアクションをテストして展開後のテキストを確認します。<code>showLabel</code> を変更して保存し、もう一度テストします。テンプレートを再インポートしなくても既存アクションは更新された値を使えます。</li></ol><p>テンプレートの <code>params</code> は適用時に置換され、<code>globals</code> は実行時に読まれます。存在しない実行時キーは空文字になるため、送信先や識別子で使う前に綴りを確認してください。イベントのパスは各フィールドの変数候補からトリガーに合うものを選びます。</p><h2 id="review-cloud-changes-separately" tabindex="-1">Cloud の変更は別途確認する <a class="header-anchor" href="#review-cloud-changes-separately" aria-label="Permalink to &quot;Cloud の変更は別途確認する {#review-cloud-changes-separately}&quot;">​</a></h2><p>変数の <strong>変更</strong> では、対応ホスト上で送信、取得、適用・採用、取り下げを確認付きで実行できます。先にローカル編集を保存し、比較を選び、型と値を確認して方向を明示的に選びます。Cloud 候補の取得とローカル適用は別操作です。共有値の取り下げとローカル行の削除も異なります。</p><p>シークレットや送信禁止の値は比較でマスクされ、この経路では送信できません。制限を回避するためにシークレットを通常テキストに変えないでください。</p><h2 id="expected-result-status-and-recovery" tabindex="-1">期待される結果・提供状況と対処 <a class="header-anchor" href="#expected-result-status-and-recovery" aria-label="Permalink to &quot;期待される結果・提供状況と対処 {#expected-result-status-and-recovery}&quot;">​</a></h2><p>ローカル変数と、ホスト機能に応じた確認付き共有を利用できます。ローカル保存で自動アップロードは行われません。不正なキー、型に合わない値、古いリビジョンでは保存できません。強調された欄を修正するか、再読み込みしてから再試行します。アカウントの問題は <a href="./../cloud/account.html">Cloud アカウント</a>、比較の動作は <a href="./../cloud/changes.html">変更</a> を参照してください。</p>',13)])])}const b=a(r,[["render",l]]);export{p as __pageData,b as default};
